[
  {
    "statement": "Several methods have shown effectiveness in reducing unwanted catch.",
    "citations": [
      "2722",
      "2728",
      "2142",
      "2693",
      "3826"
    ]
  },
  {
    "statement": "Specific cost-effectiveness data for methods to reduce unwanted catch was not provided in the available evidence.",
    "citations": []
  },
  {
    "statement": "Size-sorting mesh funnels, also known as sieve nets, on prawn and shrimp trawls consistently reduced unwanted fish catches in North Sea studies.",
    "citations": [
      "2722"
    ]
  },
  {
    "statement": "Trawl gear modifications with size-sorting escape grids reduced unwanted catches in 6 of 16 studies.",
    "citations": [
      "2728"
    ]
  },
  {
    "statement": "The effectiveness of trawl gear modifications with size-sorting escape grids varied by fish species, light conditions, and net type.",
    "citations": [
      "2728"
    ]
  },
  {
    "statement": "Alternative fishing methods like traps showed mixed results for reducing unwanted catch.",
    "citations": [
      "2142"
    ]
  },
  {
    "statement": "Alternative fishing methods like traps also reduced commercial catch in some cases.",
    "citations": [
      "2142"
    ]
  },
  {
    "statement": "Governance approaches showed promise in reducing unwanted catch.",
    "citations": [
      "2693",
      "3826"
    ]
  },
  {
    "statement": "Catch limits or quotas for non-commercial species reduced unwanted catch in 2 of 3 cases across the Atlantic and Pacific Oceans.",
    "citations": [
      "2693"
    ]
  },
  {
    "statement": "Real-time catch information technology reduced unwanted catch in 2 of 3 cases in the Pacific and Atlantic Oceans.",
    "citations": [
      "3826"
    ]
  },
  {
    "statement": "The documents lack specific cost-benefit analyses to determine which method for reducing unwanted catch is most economically efficient.",
    "citations": []
  },
  {
    "statement": "The documents focused on biological effectiveness instead of economic efficiency.",
    "citations": []
  }
]
